contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // input: distributor address, reward token address, amount to notify
    function run(address distributor, address rewardToken, uint256 amount) public payable {
        // Precondition: rewardToken must have been added by owner; since owner is deployer of C (the checker deploys C),
        // we cannot call addReward (onlyOwner) here because msg.sender is this contract. So require that rewardToken was added
        // by constructor of C is not guaranteed. But we can conservatively require amount > 0 and caller equality for notify.
        require(amount > 0, "amount>0");

        // Read previous periodFinish
        uint40 beforeFinish = c.rewardPeriodFinish(rewardToken);

        // Make the caller be the distributor: the contract invoking c.notifyRewardAmount is this contract, so we need
        // distributor to equal the stored rewardDistributor in c. We cannot set c.rewardDistributor (onlyOwner), so this
        // may cause notifyRewardAmount to revert. We catch revert and record it.
        bool reverted;
        try c.notifyRewardAmount(rewardToken, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint40 afterFinish = c.rewardPeriodFinish(rewardToken);

        // General rule: if the call did not revert then afterFinish is >= block.timestamp and afterFinish > beforeFinish
        // (since amount>0 and notify extends periodFinish to block.timestamp + DURATION, which is > block.timestamp and
        // should be greater than previous finish when successful with amount>0). If it reverted, no guarantee on periodFinish,
        // but we still assert that if not reverted then this holds.
        assert(reverted || (afterFinish >= uint40(block.timestamp) && afterFinish > beforeFinish));
    }

    receive() external payable {}
}

