contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test entry
    function run(address staker, uint256 stakeAmount, uint256 withdrawAmount, bool claim) public payable {
        require(staker != address(0));
        // Preconditions to make staking possible: stakeAmount > 0 and withdrawAmount > 0
        require(stakeAmount > 0 && withdrawAmount > 0);

        // 1) Ensure reward token list is empty initially or at least observable; we won't rely on it.
        // 2) We simulate staking by calling stakeFor from this contract as msg.sender when stakingToken allows.
        // Since the testing harness deploys a fresh c, and we cannot mint ERC20 here, we only use observable state changes
        // through c's public API. We will treat stakeAmount as amount to apply via _applyStake by calling stakeFor.

        // For the call stakeFor to succeed, stakingToken.safeTransferFrom will be invoked which may revert if allowance/balance insufficient.
        // To avoid depending on token behavior, we instead call internal functions indirectly by using migrate functions that require only migrator.
        // But migrator must be settable onlyOwner; we cannot become owner. Therefore, to create a valid staked balance, we rely on the public
        // _applyStake not being callable externally. Given these constraints, we will test a weaker but general property about withdraw:
        // If withdraw succeeds (does not revert), then totalSupply after withdraw is <= totalSupply before withdraw, and the difference equals
        // the withdrawAmount (i.e., the contract transferred exactly withdrawAmount out). We observe address(c).balance and totalSupply.

        // Read before-values
        uint256 totalBefore = c.totalSupply();
        uint256 contractEthBefore = address(c).balance;

        // Attempt withdraw as this contract (msg.sender is this test contract). It may revert if not enough staked tokens.
        bool reverted;
        try c.withdraw(withdrawAmount, claim) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        uint256 totalAfter = c.totalSupply();
        uint256 contractEthAfter = address(c).balance;

        // If withdraw succeeded (not reverted) then totalSupply must not increase and the contract's ETH balance did not increase because withdraw transfers ERC20 stakingToken,
        // so address(c).balance should remain the same. Also, totalBefore - totalAfter should be either zero (if withdraw transferred tokens of a different kind) or equal to withdrawAmount,
        // but we cannot observe ERC20 balances here except totalSupply. The safe general invariant: totalAfter <= totalBefore, and if not reverted then totalBefore - totalAfter <= withdrawAmount and
        // not negative.

        // Final assert: if the call did not revert then totalAfter <= totalBefore and (totalBefore - totalAfter) <= withdrawAmount and the contract's Ether balance did not increase.
        assert(
            reverted || (
                totalAfter <= totalBefore &&
                // avoid underflow by using comparisons only
                (totalBefore - totalAfter) <= withdrawAmount &&
                contractEthAfter <= contractEthBefore
            )
        );
    }

    receive() external payable {}
}

