contract InvMutTest {
    C c;
    address distributor;
    IERC20 token;

    constructor(C _c) {
        c = _c;
        // set distributor to some address controllable by this test
        distributor = address(this);
    }

    // allow receiving ERC20 tokens via a minimal mock: we assume an ERC20 compliant token exists at `token`
    // The test will accept arbitrary token address as input and relies only on public interface of C.

    // single public test function
    function run(address _rewardToken, address _stakingToken, uint256 _amount) public payable {
        require(_rewardToken != address(0));
        require(_amount > 0);

        // Observe initial values
        uint40 beforeFinish = c.rewardPeriodFinish(_rewardToken);
        uint256 beforeBalance = address(c).balance;

        // set rewardDistributor in c by owner: c was deployed by checker and InvMutTest is the deployer of c per instructions,
        // but only owner can call setRewardDistributor. The constructor of C set owner to deployer (checker) not InvMutTest,
        // so we cannot call onlyOwner functions. Instead we assume rewardDistributor is already set to this contract by test harness.
        // The property must hold when notifyRewardAmount is called by rewardDistributor. We attempt to call and capture revert.

        bool reverted;
        bytes memory returndata;
        // Try calling notifyRewardAmount; it will require msg.sender == rewardDistributor inside C.
        try c.notifyRewardAmount(_rewardToken, _amount) {
            reverted = false;
        } catch (bytes memory reason) {
            reverted = true;
            returndata = reason;
        }

        uint40 afterFinish = c.rewardPeriodFinish(_rewardToken);
        uint256 afterBalance = address(c).balance;

        // If call reverted then we cannot assert state change; in that case the general rule is that if call succeeded
        // then periodFinish equals block.timestamp + DURATION and contract balance increased by _amount.
        // We therefore assert: either call reverted, or both conditions hold.

        // compute expected finish: DURATION is 86400 * 7 = 604800
        uint256 expectedFinish = block.timestamp + 604800;

        assert(reverted || (uint256(afterFinish) == expectedFinish && afterBalance >= beforeBalance + _amount));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We take parameters: staking token address (to observe balanceOf on test), beneficiary, amount
    // The test assumes the staking token at _stakingToken implements IERC20 and that this contract has approved c to pull tokens.
    function run(address _stakingToken, address _for, uint256 _amount) public payable {
        require(_stakingToken != address(0));
        require(_for != address(0));
        require(_amount > 0);

        IERC20 token = IERC20(_stakingToken);

        // Observe before values
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBalanceFor = c.balanceOf(_for);
        uint256 beforeTokenBalanceContract = token.balanceOf(address(c));
        uint256 beforeTokenBalanceSender = token.balanceOf(address(this));

        // The call that may change c's state: stakeFor is public and will call stakingToken.safeTransferFrom(msg.sender, address(this), _amount);
        // We call c.stakeFor(_for, _amount) directly. This is a top-level state-changing call.
        bool reverted;
        try c.stakeFor(_for, _amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after values (views only)
        uint256 afterTotal = c.totalSupply();
        uint256 afterBalanceFor = c.balanceOf(_for);
        uint256 afterTokenBalanceContract = token.balanceOf(address(c));
        uint256 afterTokenBalanceSender = token.balanceOf(address(this));

        // General rule: if stakeFor did not revert, then totalSupply and the beneficiary's balance increased by _amount,
        // and the staking token balance of the contract increased by at least _amount (and sender decreased accordingly if token is standard ERC20).
        // We assert a single general condition combining these observations.
        assert(reverted || (
            afterTotal == beforeTotal + _amount &&
            afterBalanceFor == beforeBalanceFor + _amount &&
            afterTokenBalanceContract >= beforeTokenBalanceContract + _amount
        ));
    }

    receive() external payable {}
}

