        // Observe before values
        uint40 beforeFinish = c.rewardPeriodFinish(_rewardToken);
        uint256 beforeBalance = IERC20(_rewardToken).balanceOf(address(c));

        // The state-changing call must be a top-level call. We call notifyRewardAmount which requires msg.sender == rewardDistributor.
        // To satisfy that in some executions, the test environment will arrange c.rewardDistributor() == address(this) in some runs.
        bool reverted;
        try c.notifyRewardAmount(_rewardToken, _amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after values (views only)
        uint40 afterFinish = c.rewardPeriodFinish(_rewardToken);
        uint256 afterBalance = IERC20(_rewardToken).balanceOf(address(c));

        // General rule: if the call did not revert, then the periodFinish must have advanced (strictly greater than before)
        // and the contract's token balance must have increased by at least _amount.
        // If it reverted, we make no claim.
        assert(reverted || (afterFinish > beforeFinish && afterBalance >= beforeBalance + _amount));
    }

    receive() external payable {}
}

