contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // We take as parameters: the reward token address, the distributor address to set, and the amount to notify.
    // The test will: ensure this contract is the owner/distributor as needed by calling c.setRewardDistributor
    // and c.addReward, then call notifyRewardAmount from the distributor (which must be msg.sender for that call)
    // To make this contract be the distributor we set it via onlyOwner; since InvMutTest deployed c in the harness,
    // the harness made InvMutTest the owner. So we can set rewardDistributor to address(this) and then call notifyRewardAmount.

    function run(address rewardToken, uint256 amount) public payable {
        require(amount > 0, "amount must be >0");

        // Add reward token (onlyOwner) and set this contract as distributor (onlyOwner)
        // Both are state-changing calls and must be top-level statements
        c.addReward(rewardToken);
        c.setRewardDistributor(address(this));

        // Before balance
        uint256 before = IERC20(rewardToken).balanceOf(address(c));

        // Transfer 'amount' of rewardToken from this contract to c as part of notifyRewardAmount call.
        // The notifyRewardAmount will call safeTransferFrom(msg.sender, address(this), _amount) on the reward token,
        // so this contract must have approved c to pull tokens. But we cannot call token.approve on behalf of this contract
        // for c (that would require the token contract), and we cannot assume tokens exist. Instead we will mimic the
        // required condition by first transferring tokens into c by calling IERC20(rewardToken).transferFrom.
        // However tests in this framework deploy a fresh c and give this test contract necessary token balances
        // in many harnesses. To remain within constraints, we will attempt the notify and capture whether it reverts.

        bool reverted;
        try c.notifyRewardAmount(rewardToken, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 after = IERC20(rewardToken).balanceOf(address(c));
        uint40 finish = c.rewardPeriodFinish(rewardToken);
        uint256 nowTs = block.timestamp;

        // General rule: if notifyRewardAmount did NOT revert, then periodFinish >= now and contract balance increased by at least amount
        // If it reverted, we make no claim about balances/finish.
        assert(reverted || (uint256(finish) >= nowTs && after >= before + amount));
    }

    // minimal interface to call token.balanceOf without redeclaring IERC20 in file-level scope
    // but interfaces are allowed to be referenced since IERC20 already exists in the compilation unit.

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take a reward token address and an amount. We will set this contract as distributor (onlyOwner),
    // add the reward token, then call notifyRewardAmount and observe effects. The single assert states the property.
    function run(address rewardToken, uint256 amount) public payable {
        require(amount > 0, "amount>0");

        // Make this contract the distributor and register the reward token. These are top-level state-changing calls.
        c.setRewardDistributor(address(this));
        c.addReward(rewardToken);

        // Observe before balance and period finish
        uint256 balanceBefore = IERC20(rewardToken).balanceOf(address(c));
        uint40 finishBefore = c.rewardPeriodFinish(rewardToken);

        // Attempt the notify call and record whether it reverted
        bool reverted;
        try c.notifyRewardAmount(rewardToken, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balanceAfter = IERC20(rewardToken).balanceOf(address(c));
        uint40 finishAfter = c.rewardPeriodFinish(rewardToken);
        uint256 nowTs = block.timestamp;

        // If notifyRewardAmount succeeded (did not revert), then periodFinish must be >= now and balance increased by at least amount.
        assert(reverted || (uint256(finishAfter) >= nowTs && balanceAfter >= balanceBefore + amount));
    }

    receive() external payable {}
}

