    constructor(C _c) {
        c = _c;
        token = c.stakingToken();
    }

    // params: from is the address that will be the msg.sender for token approvals/transfers
    // We cannot change msg.sender when calling c from this contract, so we emulate by having
    // this contract hold tokens and approve c. amount is the stake amount.
    function run(uint256 initialBalance, uint256 amount) public payable {
        require(address(this).balance >= 0);

        // Preconditions: ensure this contract has enough staking tokens to transfer
        // We only can observe through public interface, so we assume token is a standard ERC20.
        // Setup: minting isn't available; instead, we require initialBalance >= amount so safeTransferFrom will succeed
        // but we cannot enforce token internals. To keep the assertion general, we will call stakeFor and
        // observe behavior: either it reverts for amount==0 or it increases totals correctly.

        // Record before-values
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBalance = c.balanceOf(address(this));
        uint256 beforeContractTokenBal = token.balanceOf(address(c));

        bool reverted;
        // Attempt to stakeFor this contract for itself. stakeFor requires msg.sender to have approved tokens.
        // We try-catch to detect revert.
        try c.stakeFor(address(this), amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterTotal = c.totalSupply();
        uint256 afterBalance = c.balanceOf(address(this));
        uint256 afterContractTokenBal = token.balanceOf(address(c));

        // General rule:
        // - If amount == 0 then stakeFor must revert (contract enforces "Cannot stake 0").
        // - If stakeFor did not revert then totalSupply and user's balance increased by exactly amount,
        //   and the staking token balance held by the contract is non-decreasing by at least amount.
        assert(
            (amount == 0 ? reverted : true) &&
            (reverted ? true : (afterTotal == beforeTotal + amount && afterBalance == beforeBalance + amount && afterContractTokenBal >= beforeContractTokenBal + amount))
        );
    }

    receive() external payable {}
}

