    // This function will perform approvals and then call stakeFor on c from this contract (msg.sender for c calls is this contract)
    function run(address owner, address staker, uint256 amount) public payable {
        require(amount > 0, "need positive amount");

        // Ensure this contract has enough staking tokens to transferFrom owner -> c.
        // We cannot mint tokens; but we can only proceed if owner has enough and has approved this contract.
        // To make the test generally checkable, we only assert the invariant relative to observed preconditions.

