    // amount: the reward amount to notify
    // callerIsDistributor: whether this contract should act as distributor by having been set as rewardDistributor in c's constructor deploy (checker deploys c so this param lets us express relation)
    function run(address distributor, address rewardToken, uint256 amount) public payable {
        // We only observe via public surface; require nothing about external token balances.
        // Read pre-state
        uint40 beforeFinish = c.rewardPeriodFinish(rewardToken);
        uint256 beforeTotal = c.totalSupply();
        address currentDistributor = c.rewardDistributor();

        // We will attempt to call notifyRewardAmount as this contract (msg.sender == address(this)).
        // For the property we consider the case where this contract is the configured distributor.
        // If it is not the configured distributor, the call must revert with "not distributor".
        bool reverted;
        try c.notifyRewardAmount(rewardToken, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint40 afterFinish = c.rewardPeriodFinish(rewardToken);
        uint256 afterTotal = c.totalSupply();

        // General rule:
        // - If this contract was the configured distributor (currentDistributor == address(this)) and amount>0 and reward token was known (beforeFinish != 0), then notifyRewardAmount should not revert, afterFinish > block.timestamp (i.e. > beforeFinish if beforeFinish <= block.timestamp) and totalSupply unchanged.
