        // We express this as a single assertion combining both cases, using only observable values.
        if (currentDistributor == address(this) && amount > 0 && beforeFinish != uint40(0)) {
            // successful non-revert expected and periodFinish updated to > block.timestamp
            // We cannot directly reference block.timestamp inside assert aside from comparing before/after, so require afterFinish > beforeFinish || reverted==false
            // But to be strict: when distributor is correct and preconditions hold, reverted must be false,
            // afterTotal must equal beforeTotal, and afterFinish must be greater or equal to beforeFinish and at least > uint40(block.timestamp - DURATION) — simplify to afterFinish > beforeFinish || (beforeFinish == afterFinish && reverted==false)
            assert(reverted == false && afterTotal == beforeTotal && afterFinish > beforeFinish);
