        bool reverted;
        try c.notifyRewardAmount(rewardToken, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint40 newFinish = c.rewardPeriodFinish(rewardToken);

        // If the call reverted then nothing should have changed: newFinish equals priorFinish.
        // If it succeeded then newFinish must be >= block.timestamp and <= block.timestamp + DURATION.
        // Compose a general assertion covering both cases.
        uint256 nowTs = block.timestamp;
        uint256 DURATION = c.DURATION();

