contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry performing the property test
    // Parameters:
    //  - staker: the address for which getRewards will be invoked (as msg.sender of calls from this contract)
    function run(address staker) public payable {
        require(staker != address(0), "staker nonzero");

        // Observe before-values: totalSupply, c's ETH balance, and per-reward-token claimable and token balances
        uint256 beforeTotal = c.totalSupply();
        uint256 cEthBefore = address(c).balance;

        // read rewardTokens length indirectly by iterating until revert would occur is not possible; use public array getter via try to read index 0..N until it reverts.
        // We'll conservatively probe up to 8 tokens to form an index set (if fewer exist, calls will revert and be skipped).
        address[8] memory tokens;
        uint256 tokenCount = 0;
        for (uint256 i = 0; i < 8; i++) {
            try c.rewardTokens(i) returns (address t) {
                // only accept nonzero entries
                if (t != address(0)) {
                    tokens[tokenCount] = t;
                    tokenCount++;
                }
            } catch {
                break;
            }
        }

        // For each observed token, record claimableRewards[staker][token] and c's token balance before
        uint256[8] memory claimableBefore;
        uint256[8] memory tokenBalanceBefore;
        for (uint256 j = 0; j < tokenCount; j++) {
            address tk = tokens[j];
            // call the public getter for claimableRewards via the mapping public accessor: claimableRewards(address,address)
            claimableBefore[j] = c.claimableRewards(staker, tk);
            tokenBalanceBefore[j] = IERC20(tk).balanceOf(address(c));
        }

        // Now perform the state-changing call under test: getRewards(staker)
        bool reverted;
        try c.getRewards(staker) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after-values
        uint256 afterTotal = c.totalSupply();
        uint256 cEthAfter = address(c).balance;
        uint256[8] memory tokenBalanceAfter;
        for (uint256 j = 0; j < tokenCount; j++) {
            address tk = tokens[j];
            tokenBalanceAfter[j] = IERC20(tk).balanceOf(address(c));
        }

        // General rule (single assert):
        // - getRewards must not change totalSupply
        // - getRewards must not transfer ETH (contract ETH balance unchanged)
        // - For each observed reward token, the contract's token balance may have decreased by at most the previously claimable amount for that staker.
        //   (i.e., it cannot send out more tokens than were recorded claimableBefore)
        // - If the call reverted, then it's allowed but we still require that nothing observable improved: totalSupply and balances remain equal to before.
        bool balancesOkay = true;
        for (uint256 j = 0; j < tokenCount; j++) {
            // after balance must be >= beforeBalance - claimableBefore (i.e., decreased by at most claimableBefore)
            // rearranged to avoid underflow in Solidity checked arithmetic inside assert: check beforeBalance >= tokenBalanceAfter + (0) ?
            // We compute allowedMin = tokenBalanceBefore[j] >= claimableBefore[j] ? tokenBalanceBefore[j] - claimableBefore[j] : 0
            uint256 allowedMin;
            if (tokenBalanceBefore[j] >= claimableBefore[j]) {
                allowedMin = tokenBalanceBefore[j] - claimableBefore[j];
            } else {
                // if claimable reported exceeds contract balance, then it's impossible to have sent more than before balance
                allowedMin = 0;
            }
            if (tokenBalanceAfter[j] < allowedMin) {
                balancesOkay = false;
            }
        }

        assert(
            // if reverted: nothing changed
            (reverted && afterTotal == beforeTotal && cEthAfter == cEthBefore && balancesOkay)
            ||
            // if not reverted: totalSupply and ETH unchanged, and token decreases limited by claimable amounts
            (!reverted && afterTotal == beforeTotal && cEthAfter == cEthBefore && balancesOkay)
        );
    }

    // allow receiving ETH if needed
    receive() external payable {}
}

