contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // params: the reward token address, the distributor address, and amount to notify
    function run(address rewardToken, address distributor, uint256 amount) public payable {
        require(rewardToken != address(0) && distributor != address(0) && amount > 0, "invalid params");

        // The test deployer (the test runner) is the owner of fresh c, per harness description.
        // Add the reward token first (onlyOwner required).
        c.addReward(rewardToken);

        // Set the reward distributor to the supplied distributor (onlyOwner required).
        c.setRewardDistributor(distributor);

        // read pre-state: previous periodFinish and contract token balance
        uint40 beforeFinish = c.rewardPeriodFinish(rewardToken);
        uint256 beforeBal = IERC20(rewardToken).balanceOf(address(c));

        // Prepare: the distributor must call notifyRewardAmount and transfer tokens in.
        // We simulate the external distributor calling notifyRewardAmount by invoking it from this contract
        // but the contract requires msg.sender == rewardDistributor. So we first set this contract as the distributor.
        // Note: setRewardDistributor was called with 'distributor' above; override to address(this) so we can call.
        // OnlyOwner can call setRewardDistributor, and the owner is the deployer (harness), so we can call again.
        c.setRewardDistributor(address(this));

        // Now transfer 'amount' of rewardToken from this contract to c as part of notifyRewardAmount.
        // To allow that, this contract must hold 'amount' tokens. We require the test environment supplies them.
        require(IERC20(rewardToken).balanceOf(address(this)) >= amount, "test contract lacks tokens");

        // Approve c to pull tokens from this contract
        IERC20(rewardToken).approve(address(c), amount);

        bool reverted;
        try c.notifyRewardAmount(rewardToken, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read post-state
        uint40 afterFinish = c.rewardPeriodFinish(rewardToken);
        uint256 afterBal = IERC20(rewardToken).balanceOf(address(c));

        // General rule: if notifyRewardAmount did not revert, then periodFinish strictly increased (or at least moved forward to > before) and c's token balance increased by exactly amount
        assert(
            reverted || (afterFinish > beforeFinish && afterBal == beforeBal + amount)
        );
    }

    receive() external payable {}
}

