contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entrypoint for the property test
    // params:
    // - distributor: the address that will be set as rewardDistributor (must be owner to set via setRewardDistributor)
    // - rewardToken: token to add and notify
    // - amount: amount passed to notifyRewardAmount
    // - owner: the owner address used to call setRewardDistributor and addReward (we simulate by calling c.setRewardDistributor from this contract after c was deployed by checker — note: checker deploys c with InvMutTest as msg.sender)
    function run(address distributor, address rewardToken, uint256 amount) public payable {
        require(amount > 0, "amount>0");

        // At deployment time of C (by checker) constructor set owner to msg.sender, which is this contract.
        // So this contract is the owner and may call owner-only functions on c.

        // 1) register reward token
        // addReward requires rewardData[lastUpdateTime]==0, which is true for fresh c
        c.addReward(rewardToken);

        // 2) set reward distributor to provided distributor address
        c.setRewardDistributor(distributor);

        // 3) ensure this contract approves distributor to transfer reward tokens on its behalf if distributor is going to call notify.
        // However notifyRewardAmount requires msg.sender == rewardDistributor, so we will call notifyRewardAmount from this contract only if distributor == address(this).
        // The property must account for both cases. We'll attempt notifyRewardAmount as if called by rewardDistributor (i.e., only if distributor==address(this)).

        bool notified;
        bool reverted;
        uint40 beforeFinish = c.rewardPeriodFinish(rewardToken);
        uint256 beforeBalance = IERC20(rewardToken).balanceOf(address(c));

        if (distributor == address(this)) {
            // need to have the reward tokens in this contract and approve c to pull them
            // We cannot mint tokens; but we can try to call notifyRewardAmount and catch revert.
            // Call notify with try/catch to observe revert
            try c.notifyRewardAmount(rewardToken, amount) {
                notified = true;
                reverted = false;
            } catch {
                notified = false;
                reverted = true;
            }
        } else {
            // If distributor is not this contract, we cannot simulate external account calling notifyRewardAmount in a single transaction
            // So we mark notified=false and reverted=true to reflect that notify was not executed by rewardDistributor here.
            notified = false;
            reverted = true;
        }

        uint40 afterFinish = c.rewardPeriodFinish(rewardToken);
        uint256 afterBalance = IERC20(rewardToken).balanceOf(address(c));

        // General rule to assert:
        // If notifyRewardAmount was successfully executed (not reverted) then:
        //  - afterFinish should equal uint40(block.timestamp + c.DURATION())
        //  - afterBalance should be >= beforeBalance + amount
        // Otherwise (notify didn't succeed or wasn't called), nothing is required beyond that state didn't magically increase the periodFinish to a future > before iff not notified.

        if (notified && !reverted) {
            // We use the publicly accessible constant DURATION via reading it through c.DURATION().
            uint256 dur = c.DURATION();
            // assert the two properties
            assert(afterFinish == uint40(block.timestamp + dur) && afterBalance >= beforeBalance + amount);
        } else {
            // If notify wasn't successfully executed here, require that either finish stayed the same or did not change to the exact expected new finish.
            // This avoids asserting a constant. We require that if finish changed to the expected value then balance must have increased accordingly.
            uint256 dur = c.DURATION();
            bool finishMatches = (afterFinish == uint40(block.timestamp + dur));
            bool balanceIncreased = (afterBalance >= beforeBalance + amount);
            // If finishMatches then balanceIncreased must hold; otherwise no restriction.
            assert(!finishMatches || balanceIncreased);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Params:
    // - distributor: the address to set as rewardDistributor (we'll set it when this contract is owner)
    // - rewardToken: token to add and (maybe) notify
    // - amount: amount passed to notifyRewardAmount
    function run(address distributor, address rewardToken, uint256 amount) public payable {
        require(amount > 0, "amount>0");

        // This contract was the deployer/owner of C according to the harness description, so it can call owner-only functions.
        // 1) register reward token
        c.addReward(rewardToken);

        // 2) set reward distributor
        c.setRewardDistributor(distributor);

        // Record observable before-values
        uint40 beforeFinish = c.rewardPeriodFinish(rewardToken);
        uint256 beforeBalance = IERC20(rewardToken).balanceOf(address(c));

        // 3) Attempt to call notifyRewardAmount from THIS contract (succeeds only if distributor == address(this))
        bool notifySucceeded;
        bool notifyReverted;
        // We must perform the state-changing call as a top-level statement. Use try/catch which is allowed top-level.
        try c.notifyRewardAmount(rewardToken, amount) {
            notifySucceeded = true;
            notifyReverted = false;
        } catch {
            notifySucceeded = false;
            notifyReverted = true;
        }

        // Read after-values
        uint40 afterFinish = c.rewardPeriodFinish(rewardToken);
        uint256 afterBalance = IERC20(rewardToken).balanceOf(address(c));

        // Single general assertion about the contract's behavior.
        // If the notify call succeeded (i.e., it was executed by the designated distributor and did not revert),
        // then the recorded periodFinish must equal block.timestamp + DURATION and the contract's balance must have increased by at least amount.
        uint256 dur = c.DURATION();
        assert(
            // only enforce the strong postcondition when we actually executed notify successfully from this contract
            (!notifySucceeded) || (afterFinish == uint40(block.timestamp + dur) && afterBalance >= beforeBalance + amount)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params:
    // - staker: address that will stake tokens for testing (must be non-zero)
    // - stakeAmount: amount to stake before attempting withdraw
    // - withdrawAmount: amount to withdraw via withdraw()
    // - claim: whether to claim rewards on withdraw
    function run(address staker, uint256 stakeAmount, uint256 withdrawAmount, bool claim) public payable {
        require(staker != address(0), "staker!=0");
        require(stakeAmount > 0, "stakeAmount>0");

        // This test contract is the owner/deployer of c per harness; it can call addReward etc if needed.
        // We will emulate staking by calling stakeFor as msg.sender (which will attempt a transferFrom).
        // To make stakeFor succeed, we need the stakingToken to allow this contract to transferFrom staker.
        // We cannot manipulate external ERC20 allowances here, so instead we use stakeFor with staker == msg.sender (this contract).
        // Therefore require that the provided staker equals address(this).
        require(staker == address(this), "staker must be this contract for transferFrom to succeed");

        // Precondition: ensure this contract has enough staking token balance by assuming the staking token may be a test ERC20
        // The harness ensures token behaviors; we just proceed to call stakeFor/stake.

        // 1) Stake stakeAmount as this contract using stakeFor (top-level state-changing call)
        c.stakeFor(staker, stakeAmount);

        // Observe before-values
        uint256 beforeBalance = c.balanceOf(staker);
        uint256 beforeTotal = c.totalSupply();

        // 2) Attempt withdraw(withdrawAmount, claim) as staker == this contract
        bool withdrew;
        bool reverted;
        try c.withdraw(withdrawAmount, claim) {
            withdrew = true;
            reverted = false;
        } catch {
            withdrew = false;
            reverted = true;
        }

        // Observe after-values
        uint256 afterBalance = c.balanceOf(staker);
        uint256 afterTotal = c.totalSupply();

        // General rule: withdraw never increases the staker's recorded balance or the total supply.
        // If the call reverted, both observables must remain equal to before-values.
        // If the call succeeded, both observables must have decreased by at most withdrawAmount and in lockstep with each other
        // and the decrease in each is <= before values.
        assert(
            // no increase allowed
            afterBalance <= beforeBalance && afterTotal <= beforeTotal
            && (
                // if reverted: nothing changed
                reverted ? (afterBalance == beforeBalance && afterTotal == beforeTotal)
                : (
                    // if succeeded: the decreases are consistent and bounded by withdrawAmount
                    (beforeBalance - afterBalance <= withdrawAmount)
                    && (beforeTotal - afterTotal <= withdrawAmount)
                    // and the decreases are equal (withdrawing updates both supply and balance by same amount)
                    && (beforeBalance - afterBalance == beforeTotal - afterTotal)
                )
            )
        );
    }

    receive() external payable {}
}
